 static int NativeRestoreWatch(string[] a){int pid=int.Parse(a[1]);string dir=a[2],flag=Path.Combine(dir,"restore-up.required");var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<180000){try{if(Process.GetProcessById(pid).HasExited)break;}catch{break;}Thread.Sleep(100);}if(!File.Exists(flag))return 0;var h=Native.Load(Path.Combine(dir,"baseline-up.cur"),0);bool ok=Native.SetSystemCursor(h,32516);string hash=Native.PixelHash(Native.LoadCursorW(IntPtr.Zero,new IntPtr(32516)));bool match=ok&&hash==File.ReadAllText(Path.Combine(dir,"baseline.hash"));File.WriteAllText(Path.Combine(dir,"watchdog.json"),JsonSerializer.Serialize(new{ok,match},Json));if(match)File.Delete(flag);return match?0:2;}
