 static void NativeBenchCase(string name,string[] names,int max,int hz,bool cached,IntPtr timer){var selected=names.Select(n=>cases.Single(c=>c.Name==n)).ToArray();var svgs=new List<SKSvg>();var handles=new List<IntPtr>();try{foreach(var c in selected){var s=new SKSvg();using var stream=new MemoryStream(Encoding.UTF8.GetBytes(AtSize(c.Xml,256)));s.Load(stream);svgs.Add(s);if(cached){using var b=RasterPicture(s,max);handles.Add(Win.Cursor(b,c.HotX,c.HotY));}}
  // Warm the rasterizer and GDI before recording CPU and wall time.
  for(int n=0;n<6;n++){using var b=RasterPicture(svgs[n%svgs.Count],256);var h=Win.Cursor(b,selected[n%selected.Length].HotX,selected[n%selected.Length].HotY);Native.DestroyCursor(h);}
  var cpu=Process.GetCurrentProcess();GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();var before=Resources();double usedBefore=cpu.TotalProcessorTime.TotalMilliseconds;long origin=Stopwatch.GetTimestamp();int lastSlot=-1,count=0,skipped=0;var work=new List<double>();var ages=new List<double>();var sizes=new HashSet<int>();var frameTrace=new List<object>();
  while(Millis(Stopwatch.GetTimestamp()-origin)<4000){long now=Stopwatch.GetTimestamp();int slot=(int)(Millis(now-origin)*hz/1000);if(slot<=lastSlot){long due=-(long)Math.Max(1,((lastSlot+1)*1000.0/hz-Millis(now-origin))*10000);SetWaitableTimer(timer,ref due,0,IntPtr.Zero,IntPtr.Zero,false);WaitForSingleObject(timer,1000);continue;}skipped+=Math.Max(0,slot-lastSlot-1);lastSlot=slot;double t=Millis(now-origin);int frame=(int)(t/60)%selected.Length;int size=cached?max:64+(int)Math.Round((max-64)*(0.5-0.5*Math.Cos(2*Math.PI*t/2000)));sizes.Add(size);long start=Stopwatch.GetTimestamp();IntPtr h;if(cached){h=Native.CopyImage(handles[frame],2,0,0,0);}else{using var b=RasterPicture(svgs[frame],size);h=Win.Cursor(b,selected[frame].HotX,selected[frame].HotY);}if(h==IntPtr.Zero||!Native.SetSystemCursor(h,32516))throw new Exception("Native vector publication "+Marshal.GetLastWin32Error());long end=Stopwatch.GetTimestamp();work.Add(Millis(end-start));ages.Add(Millis(end-now));if(count%30==0)frameTrace.Add(new{Slot=slot,Frame=frame,Size=size,InputTimeMs=t,PresentedAtMs=Millis(end-origin)});count++;}
  double wall=Millis(Stopwatch.GetTimestamp()-origin);double used=cpu.TotalProcessorTime.TotalMilliseconds-usedBefore;work.Sort();results.Add(new{Name=name,MaxSize=max,TargetHz=hz,CachedNativeFrames=cached,PreparedVectorPictures=svgs.Count,DurationMs=wall,Publications=count,ActualPublicationsPerSecond=count*1000/wall,SkippedSchedulerSlots=skipped,DistinctSizes=sizes.Count,CpuPercentOneCore=100*used/wall,CpuPercentMachine=100*used/wall/Environment.ProcessorCount,MeanWorkMs=work.Average(),P95WorkMs=work[(int)((work.Count-1)*0.95)],MaxWorkMs=work[^1],MeanSampleAgeAtPublicationMs=ages.Average(),Before=before,After=Resources(),Trace=frameTrace});
 }finally{foreach(var h in handles)Native.DestroyCursor(h);foreach(var s in svgs)s.Dispose();}}
 static int RunNativeBench(){if(Directory.Exists(root)&&Directory.EnumerateFileSystemEntries(root).Any())throw new Exception("Run directory must be new");Directory.CreateDirectory(root);Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);LoadCases();var shared=Native.LoadCursorW(IntPtr.Zero,new IntPtr(32516));var baselineDims=Native.Dimensions(shared);string hash=Native.PixelHash(shared);File.WriteAllBytes(Path.Combine(root,"baseline-up.cur"),Native.SaveStaticCursor(shared));var disk=Native.Load(Path.Combine(root,"baseline-up.cur"),0);try{if(Native.PixelHash(disk)!=hash||Native.Dimensions(disk)!=baselineDims)throw new Exception("Backup verification");}finally{Native.DestroyCursor(disk);}File.WriteAllText(Path.Combine(root,"baseline.hash"),hash);using var watch=StartOwn(Environment.ProcessPath!,"--restore-native",Environment.ProcessId.ToString(),root);Native.GetCursorPos(out var position);var foreground=Native.GetForegroundWindow();Process? host=null;IntPtr timer=IntPtr.Zero;string? failure=null;bool restored=false;try{string exe=Path.GetFullPath(Path.Combine(project,"../NativeRoleProbe/bin/Debug/net10.0-windows/NativeRoleProbe.exe"));host=StartOwn(exe,"--host",root);IntPtr window=IntPtr.Zero;var sw=Stopwatch.StartNew();while(window==IntPtr.Zero&&sw.ElapsedMilliseconds<3000){EnumWindows((h,p)=>{GetWindowThreadProcessId(h,out var id);if(id==host.Id)window=h;return true;},IntPtr.Zero);Thread.Sleep(20);}if(window==IntPtr.Zero)throw new Exception("No external owner");Native.SetForegroundWindow(window);Native.SetCursorPos(440,320);File.WriteAllText(Path.Combine(root,"command.json"),"{\"Serial\":1,\"Role\":32516,\"Private\":false}");sw.Restart();while(!File.Exists(Path.Combine(root,"ack.json"))&&sw.ElapsedMilliseconds<3000)Thread.Sleep(10);if(!File.Exists(Path.Combine(root,"ack.json")))throw new Exception("No cursor owner ack");Thread.Sleep(150);File.WriteAllText(Path.Combine(root,"host-frozen"),"");File.WriteAllText(Path.Combine(root,"restore-up.required"),"");timer=CreateWaitableTimerExW(IntPtr.Zero,IntPtr.Zero,2,0x1F0003);if(timer==IntPtr.Zero)throw new Exception("No timer");var busy=new[]{"bibata-wait01","bibata-wait14","bibata-wait27","bibata-wait40"};NativeBenchCase("growth-bibata-pointer",new[]{"bibata-pointer"},512,60,false,timer);NativeBenchCase("growth-bibata-wait",busy,512,60,false,timer);NativeBenchCase("growth-nordzy-pointer",new[]{"nordzy-pointer"},512,60,false,timer);NativeBenchCase("growth-nordzy-wait",new[]{"nordzy-wait01"},1024,60,false,timer);NativeBenchCase("growth-bibata-wait",busy,1024,60,false,timer);NativeBenchCase("growth-bibata-wait",busy,2048,60,false,timer);NativeBenchCase("steady-cached-bibata-wait",busy,1024,60,true,timer);}
 catch(Exception e){failure=e.ToString();}finally{try{var h=Native.Load(Path.Combine(root,"baseline-up.cur"),0);bool ok=Native.SetSystemCursor(h,32516);restored=ok&&Native.PixelHash(shared)==hash&&Native.Dimensions(shared)==baselineDims;if(restored)File.Delete(Path.Combine(root,"restore-up.required"));}catch(Exception e){failure+="\nRESTORE: "+e;}File.WriteAllText(Path.Combine(root,"host-stop"),"");if(host!=null&&!host.HasExited)host.WaitForExit(2000);if(timer!=IntPtr.Zero)CloseHandle(timer);Native.SetForegroundWindow(foreground);Native.SetCursorPos(position.X,position.Y);File.WriteAllText(Path.Combine(root,"report.json"),JsonSerializer.Serialize(new{Experiment="Actual SVG-to-native cursor publication, isolated",Date=DateTimeOffset.Now,Failure=failure,Restored=restored,LogicalProcessors=Environment.ProcessorCount,PublisherCallsSetCursor=false,Renderer="Svg.Skia 5.2.3 retained vectors",Cases=results},Json));}Console.WriteLine("Native SVG benchmark restored="+restored+" failure="+failure);return restored&&failure==null?0:1;}
